"""Mount Paradise destination architecture: hospitality, gatherings, ownership and club life."""
from urllib.parse import quote
EMAIL='info@mountparadisejava.com'
def enquire(topic,label='Enquire by email'):
 return link('mailto:'+EMAIL+'?subject='+quote('Mount Paradise | '+topic),label)
def cta(topic,title='Let’s make it yours.',text='Tell us what you have in mind. Our conversation starts here.'):
 return f'<section class="section contact-band"><div><p class="eyebrow">Your next chapter</p><h2>{title}</h2><p>{text}</p></div><div>{enquire(topic)}<a class="email-address" href="mailto:{EMAIL}">{EMAIL}</a></div></section>'
def feature(image,k,title,text,url,label,dark=False):
 return f'<section class="section feature {"dark" if dark else ""}">{pic(image,title.replace("<br>"," "),k)}<div class="feature-copy"><p class="eyebrow">{k}</p><h2>{title}</h2><p>{text}</p>{link(url,label)}</div></section>'
def cards(items):
 return '<div class="destination-cards">'+''.join(f'<a class="destination-card" href="{url}"><img src="assets/{image}.jpg" alt="{title}" loading="lazy" width="900" height="600"><div><p class="eyebrow">{k}</p><h3>{title}</h3><p>{text}</p><span class="card-action">{label}</span></div></a>' for image,k,title,text,url,label in items)+'</div>'
def highlights(items):
 return '<div class="thirds">'+''.join(row(k,t,d) for k,t,d in items)+'</div>'
def placeholder(title,text):
 return f'<div class="woods-placeholder" role="img" aria-label="Photographic story coming soon: {title}"><span class="woods-mark" aria-hidden="true">AW</span><p class="eyebrow">Arvorest Woods</p><h3>{title}</h3><p>{text}</p><small>Photography coming soon</small></div>'
hero_alts.update({'main-lodge':'The Main Lodge with layered teak roofs, volcanic stone, gardens and a generous pool terrace','main-lodge-terrace':'Warm stone and teak dining terrace opening to the Main Lodge gardens','mountain-baths':'Sheltered mountain bathing pools with stone piers, timber roofs and woodland views','indoor-fitness':'Indoor fitness center with strength and cardio equipment overlooking woodland'})
metadata={}
def page(file,title,description,body):
 pages[file]=(title,body)
 metadata[file]=description
