 +cards([('main-lodge-terrace','Stay','Make a little more time.','Rooms, suites and private stays, with the mountains setting the pace.','stay.html','Explore stays'),('clubhouse-restaurant','Gather','Bring people together.','Leadership retreats, conferences, destination weddings and celebrations.','gather.html','Plan a gathering'),('signature-lodge','Live','A place of your own.','Private cabins, lodges and villas within a wider mountain community.','residences.html','Explore residences')])+'</section>'
 +feature('clubhouse-arrival','Corporate retreats / Weddings','Some occasions<br>deserve a destination.','A place to think clearly, celebrate beautifully, and spend real time together. Meeting spaces, dining terraces and places to stay make room for the whole occasion.','gather.html','Explore gatherings',True)
