 +cards([('clubhouse-restaurant','For companies & teams','Retreats & conferences','Leadership offsites, workshops, company gatherings and multi-day conferences.','corporate-retreats.html','Explore corporate gatherings'),('clubhouse-arrival','For families & friends','Weddings & celebrations','A mountain setting for vows, welcome dinners and celebrations across a weekend.','weddings.html','Explore celebrations')])+'</section>'
